  'Alle onderdelen halen de norm.':
      'Tutti gli elementi soddisfano lo standard.',
  'Deze verhoudingen gaan over de app zelf, niet over je dia\'s.':
      'Questi rapporti riguardano l\'app stessa, non le tue diapositive.',
