      'I numeri dei grafici non sono stati salvati: ora esistono solo in questa finestra:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Nel browser non esiste il ripristino dopo un arresto anomalo: se chiudi questa scheda, il lavoro non salvato va perso. Salva tu stesso la presentazione.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  La banca dati CVE locale (sei tu ad avviare il download): OciDeck recupera i dati in blocco tramite api.github.com e il file di rilascio a cui quell\'indirizzo rimanda.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Ricerca CVE (disattivata per impostazione predefinita): se è attiva, il termine di ricerca viene inviato al mirror CVE configurato e, se non trova nulla, alla banca dati europea dell\'ENISA e a MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Un video YouTube o Vimeo incorporato carica il lettore da quel servizio.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Nel browser: se il browser rifiuta di recuperare un indirizzo direttamente, OciDeck riprova tramite il server da cui proviene l\'app; quell\'indirizzo raggiunge allora quel server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'La revoca non è stata salvata. Al prossimo avvio il suo consenso sarà di nuovo valido.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Un titolo di sezione che annuncia una nuova parte della presentazione. Mantienilo breve. Aggiungi un\'immagine di sfondo dalla libreria immagini.',
  'Bronnen doorzoeken…': 'Ricerca nelle fonti…',
  'Niet doorzocht': 'Non cercato',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Questo controllo non viene eseguito nella versione web: il rilevamento dei volti richiede una libreria di sistema che il browser non ha. Usa la versione desktop per controllare i volti nelle immagini.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Il token deve avere accesso in lettura e scrittura al repository. Gitea e Forgejo non hanno ricerca lato server; OciDeck cerca in locale.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Il token deve avere lo scope repo (o granulare: Contents in lettura e scrittura).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Il token deve avere read_repository, write_repository e read_api. La ricerca lato server richiede Advanced o Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Ricerca veloce lato server — per il ritardo di indicizzazione una presentazione appena modificata potrebbe mancare.',
  'Media blijft niet bewaard in een los .md-bestand':
      'I contenuti multimediali non vengono conservati in un file .md semplice',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Le immagini, i video e l\'audio scelti in questa scheda esistono solo in memoria. Un file .md semplice non li conserva: andranno persi alla riapertura. Esporta come pacchetto .ocideck per portare con te i contenuti multimediali.',
  'Media verwijderd om privacyredenen':
      'Contenuti multimediali rimossi per motivi di privacy',
