  'Certificaat vertrouwen?': 'Considerare attendibile questo certificato?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Il certificato di questo server non è firmato da un\'autorità riconosciuta. È normale per un server self-hosted, ma è anche l\'aspetto di una connessione intercettata.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Confronta l\'impronta qui sotto con quella mostrata dal tuo server. Se coincidono, stai parlando con la macchina giusta.',
  'Uitgegeven aan': 'Rilasciato a',
  'Uitgegeven door': 'Rilasciato da',
  'Geldig tot': 'Valido fino al',
  'Vingerafdruk (SHA-256)': 'Impronta (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Viene considerato attendibile solo questo certificato. Se il server lo sostituirà, OciDeck lo chiederà di nuovo.',
  'Vertrouwen': 'Considera attendibile',
  'Certificaat bekijken': 'Visualizza certificato',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'I posti dove conservi e cerchi le tue presentazioni — cartelle su questo computer, server WebDAV, bucket S3 e repository git mescolati. Trascinali nell\'ordine che preferisci: il primo di un tipo vale come predefinito.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Archiviazione S3: quando ti colleghi a un bucket, vengono conservati l\'endpoint, il nome del bucket e la tua chiave di accesso (la chiave segreta al sicuro nel portachiavi del sistema) e le presentazioni che apri o salvi vengono inviate a quel servizio di archiviazione.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Archiviazione Git: quando ti colleghi a un repository, viene conservato il tuo token di accesso (al sicuro nel portachiavi del sistema) e le presentazioni che salvi vengono inviate a quel server come commit. Una copia di lavoro del repository resta non cifrata su questo dispositivo.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Per la lingua di questa presentazione mancano i nomi di malattie e patologie. Religione, opinione politica e termini sindacali vengono riconosciuti, e i controlli con cifra di controllo (codice fiscale, IBAN, passaporto) funzionano sempre — ma non contare sul rilevamento di una diagnosi.',
  'niet getest': 'non testata',
  'Werkte op': 'Ha funzionato il',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Hai effettuato l\'accesso, ma non hai i permessi qui. La password non è il problema: chiedi all\'amministratore i diritti su questa cartella.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Il tuo token è valido, ma non è autorizzato a farlo. Concedigli più permessi, oppure attendi se la forge applica un limite.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Il token è valido, ma non è autorizzato a farlo: concedigli più permessi sul repository.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Accesso effettuato, ma nessun permesso: la password non è il problema. Chiedi i diritti su questa cartella.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Sembra un URL DAV completo. Con Nextcloud, OciDeck ricava da sé quel percorso: qui va solo il server.',
  'Overnemen': 'Applica',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV non è configurato correttamente — controlla i dati del server in Impostazioni → Archiviazione.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Il repository git non è configurato correttamente — controlla server, proprietario e repository in Impostazioni → Archiviazione.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Il nome del server della forge non esiste o non è consultabile. Controlla che l\'URL del server non contenga errori di battitura.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Questa forge ha un indirizzo privato o LAN. Contrassegnala come interna attendibile in Impostazioni → Archiviazione.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'La forge non è raggiungibile — controlla la connessione e l\'URL del server.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Accesso alla forge non riuscito. Controlla il token: serve accesso in lettura al repository e in scrittura per salvare.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Non trovato nel repository — oppure il tuo token non può vederlo.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'La forge ha restituito un errore. Riprova più tardi.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Questo indirizzo non risponde come una forge. Il tipo di forge in Impostazioni → Archiviazione è corretto?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Configura prima un server WebDAV in Impostazioni → Archiviazione.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Necessario quando la forge è su una rete privata o domestica. Senza questa opzione il controllo di sicurezza rifiuta un indirizzo privato.',
  'Vul server-URL, eigenaar en repository in':
      'Compila URL del server, proprietario e repository',
  'de standaardbranch heet': 'il ramo predefinito si chiama',
  'die wordt voortaan gebruikt': 'verrà usato d\'ora in poi',
  'de repository is nog leeg; de eerste opslag vult hem':
      'il repository è ancora vuoto; il primo salvataggio lo riempirà',
