  // Consent / license screen (redesign).
  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Accetto la licenza EUPL 1.2 e ho letto quali dati OciDeck conserva.',
  'Lees de volledige licentie': 'Leggi la licenza completa',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck è software libero con licenza EUPL 1.2. Prima di iniziare, ti chiediamo di accettare la licenza. Di seguito puoi anche leggere quali dati OciDeck conserva su questo dispositivo e quando qualcosa lascia il tuo dispositivo.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck non raccoglie statistiche e non invia nulla di propria iniziativa verso l\'esterno. Per impostazione predefinita tutto resta su questo dispositivo. I dati lasciano questo dispositivo solo se lo scegli tu:\n\n•  Nextcloud/WebDAV: quando ti connetti a un server, il tuo nome utente e la tua password vengono conservati (la password in modo sicuro nel portachiavi del tuo sistema) e le presentazioni che apri o salvi vengono inviate a quel server.\n•  Apri tramite URL: OciDeck recupera il file dall\'indirizzo che inserisci.\n•  Media online (disattivati per impostazione predefinita): se attivati, OciDeck carica immagini e video dagli indirizzi nelle tue diapositive.\n•  I collegamenti esterni (come la licenza online) si aprono nel tuo browser.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck è fornito con la European Union Public Licence v1.2. Accettando, aderisci a questa licenza. Puoi usare, copiare, modificare e distribuire OciDeck secondo i termini della EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Per funzionare e non perdere il tuo lavoro, OciDeck conserva dati localmente su questo dispositivo:\n\n•  Le tue impostazioni e preferenze (lingua, cartelle, profili di stile e aspetto, file recenti).\n•  I tuoi materiali di presentazione: le presentazioni che salvi, le copie di ripristino automatiche e allegati come le descrizioni delle immagini.\n•  Questa scelta di consenso.\n\nPuoi rimuoverli eliminando i file o ripristinando le impostazioni.',
  'Volledige licentie online (23 officiële taalversies)':
      'Licenza completa online (23 versioni linguistiche ufficiali)',
  'Wat OciDeck op dit apparaat bewaart':
      'Cosa conserva OciDeck su questo dispositivo',
